#include <Arduino.h>

#define IR_USE_AVR_TIMER2
#include <IRremote.hpp>

// モーターのピン
#define speedPinR         9
#define RightDirectPin1  12
#define RightDirectPin2  11
#define speedPinL         6
#define LeftDirectPin1    7
#define LeftDirectPin2    8

// リモコン
#define IR_RECEIVE_PIN    4
#define IR_ADVANCE       24
#define IR_BACK          82
#define IR_RIGHT         90
#define IR_LEFT           8
#define IR_STOP          28

// 速度：0～255
#define MOVE_SPEED      180
#define TURN_SPEED      180
#define HOLD_TIMEOUT_MS 250UL
#define DIRECTION_STOP_MS 100UL

enum Direction { STOP, FORWARD, BACKWARD, RIGHT, LEFT };
Direction requested = STOP;
bool holdActive = false;
uint32_t lastReceivedAt = 0;
uint16_t lastCommand = 0;
uint16_t lastAddress = 0;
decode_type_t lastProtocol = UNKNOWN;
int appliedRight = 0;
int appliedLeft = 0;
bool stopTimingActive = false;
uint32_t stoppedAt = 0;

void stopMotors() {
  analogWrite(speedPinR, 0);
  analogWrite(speedPinL, 0);
  digitalWrite(RightDirectPin1, LOW);
  digitalWrite(RightDirectPin2, LOW);
  digitalWrite(LeftDirectPin1, LOW);
  digitalWrite(LeftDirectPin2, LOW);
  if (appliedRight != 0 || appliedLeft != 0) {
    stoppedAt = millis();
    stopTimingActive = true;
  }
  appliedRight = 0;
  appliedLeft = 0;
}

void cancelMovement() {
  requested = STOP;
  holdActive = false;
  stopMotors();
}

void checkHoldTimeout() {
  if (holdActive &&
      uint32_t(millis() - lastReceivedAt) >= HOLD_TIMEOUT_MS) {
    cancelMovement();
  }
}

Direction getDirection(uint16_t command) {
  switch (command) {
    case IR_ADVANCE: return FORWARD;
    case IR_BACK:    return BACKWARD;
    case IR_RIGHT:   return RIGHT;
    case IR_LEFT:    return LEFT;
    default:         return STOP;
  }
}

bool sameRemote(uint16_t address, decode_type_t protocol) {
  bool currentNEC = protocol == NEC || protocol == NEC2;
  bool previousNEC = lastProtocol == NEC || lastProtocol == NEC2;
  return address == lastAddress &&
         (protocol == lastProtocol || (currentNEC && previousNEC));
}

void readRemote() {
  checkHoldTimeout();
  if (!IrReceiver.decode()) {
    return;
  }
  uint16_t command = IrReceiver.decodedIRData.command;
  uint16_t address = IrReceiver.decodedIRData.address;
  decode_type_t protocol = IrReceiver.decodedIRData.protocol;
  uint8_t flags = IrReceiver.decodedIRData.flags;
  IrReceiver.resume();

  if (protocol == UNKNOWN ||
      (flags & IRDATA_FLAGS_WAS_OVERFLOW) ||
      (flags & IRDATA_FLAGS_PARITY_FAILED)) {
    cancelMovement();
    return;
  }
  if (command == IR_STOP) {
    cancelMovement();
    return;
  }
  // 同じリモコンの長押し信号で走行を継続
  if (flags & IRDATA_FLAGS_IS_REPEAT) {
    if (holdActive && command == lastCommand &&
        sameRemote(address, protocol)) {
      lastReceivedAt = millis();
    }
    return;
  }
  Direction direction = getDirection(command);
  if (direction == STOP) {
    return;
  }
  requested = direction;
  holdActive = true;
  lastReceivedAt = millis();
  lastCommand = command;
  lastAddress = address;
  lastProtocol = protocol;
}

void driveMotors() {
  if (!holdActive || requested == STOP) {
    stopMotors();
    return;
  }
  int right = 0;
  int left = 0;
  switch (requested) {
    case FORWARD:
      right = MOVE_SPEED;
      left = MOVE_SPEED;
      break;
    case BACKWARD:
      right = -MOVE_SPEED;
      left = -MOVE_SPEED;
      break;
    case RIGHT:
      right = -TURN_SPEED;
      left = TURN_SPEED;
      break;
    case LEFT:
      right = TURN_SPEED;
      left = -TURN_SPEED;
      break;
    default:
      stopMotors();
      return;
  }
  bool reversing =
      (appliedRight > 0 && right < 0) ||
      (appliedRight < 0 && right > 0) ||
      (appliedLeft > 0 && left < 0) ||
      (appliedLeft < 0 && left > 0);
  if (reversing) {
    stopMotors();
  }
  if (stopTimingActive) {
    if (uint32_t(millis() - stoppedAt) < DIRECTION_STOP_MS) {
      return;
    }
    stopTimingActive = false;
  }
  digitalWrite(RightDirectPin1, right > 0 ? HIGH : LOW);
  digitalWrite(RightDirectPin2, right < 0 ? HIGH : LOW);
  digitalWrite(LeftDirectPin1, left > 0 ? HIGH : LOW);
  digitalWrite(LeftDirectPin2, left < 0 ? HIGH : LOW);
  analogWrite(speedPinR, right < 0 ? -right : right);
  analogWrite(speedPinL, left < 0 ? -left : left);
  appliedRight = right;
  appliedLeft = left;
}

// ============================================================================
// 【追加】障害物検知：オンライン保存した7枚のフローチャートに対応
// サーボなし。元のリモコン処理・モーター処理・速度設定は変更しない。
// ============================================================================
#define Echo_PIN              3
#define Trig_PIN             10
#define LFSensor_bl           0
#define LFSensor_br           2
#define BUZZ_PIN             13
#define REAR_ACTIVE_LEVEL   LOW
#define BUZZ_ACTIVE_LEVEL   LOW

#define FRONT_DANGER_CM    10.0f
#define FRONT_WARNING_CM   15.0f
#define SENSOR_INTERVAL_MS   60UL
#define ECHO_TIMEOUT_US   15000UL
#define AVOID_SPEED         100   // 実機で停止に見えないよう回避出力を引き上げる
#define BUZZ_SLOW_MS        600UL
#define BUZZ_FAST_MS        100UL
#define BUZZ_ON_MS           35UL

// 図と同じ名前：距離SD、前方SR1/SR2、後方IR、リモコンRM、車両M
float SD = -1.0f;
bool SR1 = false;
bool SR2 = false;
bool IR = false;
uint8_t RM = 0;
uint8_t M = 0;
bool distanceValid = false;
bool sensorStarted = false;
uint32_t lastSensorAt = 0;
bool buzzerActive = false;
uint32_t buzzerStartedAt = 0;

// Main.png：元のsetupから追加で呼び出す初期化
void setupObstacleDetection() {
  digitalWrite(Trig_PIN, LOW);
  pinMode(Trig_PIN, OUTPUT);
  pinMode(Echo_PIN, INPUT);
  pinMode(LFSensor_bl, INPUT);
  pinMode(LFSensor_br, INPUT);
  digitalWrite(BUZZ_PIN, HIGH);
}

// 超音波センサ.png：10cm以下をSR1、10cm超～15cm以下をSR2にする。
// 図では省略されている解除処理も行い、前回のTRUEを残さない。
void updateUltrasonicState() {
  const uint32_t now = millis();
  if (sensorStarted && uint32_t(now - lastSensorAt) < SENSOR_INTERVAL_MS) {
    return;
  }
  sensorStarted = true;
  lastSensorAt = now;

  digitalWrite(Trig_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(Trig_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(Trig_PIN, LOW);
  const unsigned long echo = pulseIn(Echo_PIN, HIGH, ECHO_TIMEOUT_US);

  distanceValid = echo > 0;
  SD = distanceValid ? echo / 58.0f : -1.0f;
  SR1 = distanceValid && SD <= FRONT_DANGER_CM;
  SR2 = distanceValid && !SR1 && SD <= FRONT_WARNING_CM;
}

// 赤外線センサ.png：左右のどちらかがLOWなら後方障害物あり。
void updateRearInfraredState() {
  IR = digitalRead(LFSensor_bl) == REAR_ACTIVE_LEVEL ||
       digitalRead(LFSensor_br) == REAR_ACTIVE_LEVEL;
}

// 車両状態.png：元のrequestedを残し、別変数Mに最終的な動作を入れる。
void updateVehicleState() {
  // 測距中に250msを超えた場合も、元の長押し停止処理を適用する。
  checkHoldTimeout();
  switch (requested) {
    case FORWARD:  RM = 1; break;
    case BACKWARD: RM = 2; break;
    case RIGHT:    RM = 3; break;
    case LEFT:     RM = 4; break;
    default:       RM = 0; break;
  }

  // 元のOK・長押し解除を優先。前後同時検知と測距失敗も停止にする。
  if (!holdActive || RM == 0 || !distanceValid || (SR1 && IR)) {
    M = 0;
  } else if (SR1) {
    M = 1;  // 前方10cm以下：低速後退
  } else if (IR) {
    M = 2;  // 後方検知：低速前進
  } else {
    M = RM + 2;  // 1→3前進、2→4後退、3→5右、4→6左
  }
}

// 完成ブザーフロー.png：SR1またはIR、またはSR2なら警告音。
// 前方10～15cmでは、以前指定された「近いほど速く」を追加する。
void updateBuzzerState() {
  if (!(SR1 || IR || SR2)) {
    digitalWrite(BUZZ_PIN, HIGH);
    buzzerActive = false;
    return;
  }
  uint32_t period = BUZZ_FAST_MS;
  if (!SR1 && !IR && SR2) {
    const float ratio = (SD - FRONT_DANGER_CM) /
                        (FRONT_WARNING_CM - FRONT_DANGER_CM);
    period = BUZZ_FAST_MS + uint32_t(ratio * (BUZZ_SLOW_MS - BUZZ_FAST_MS));
  }
  const uint32_t now = millis();
  if (!buzzerActive || uint32_t(now - buzzerStartedAt) >= period) {
    buzzerActive = true;
    buzzerStartedAt = now;
  }
  const bool on = uint32_t(now - buzzerStartedAt) < BUZZ_ON_MS;
  digitalWrite(BUZZ_PIN, on ? BUZZ_ACTIVE_LEVEL : HIGH);
}

// 行動制御.png：M=1/2だけ追加出力。逆転時の100ms停止は元と同じ。
// M=3～6はfalseを返し、元のdriveMotors()にそのまま任せる。
bool applyObstacleMovement() {
  if (M == 0) {
    stopMotors();
    return true;
  }
  if (M != 1 && M != 2) {
    return false;
  }
  const int speed = M == 1 ? -AVOID_SPEED : AVOID_SPEED;
  const bool reversing =
      (appliedRight > 0 && speed < 0) ||
      (appliedRight < 0 && speed > 0) ||
      (appliedLeft > 0 && speed < 0) ||
      (appliedLeft < 0 && speed > 0);
  if (reversing) {
    stopMotors();
  }
  if (stopTimingActive) {
    if (uint32_t(millis() - stoppedAt) < DIRECTION_STOP_MS) {
      return true;
    }
    stopTimingActive = false;
  }
  digitalWrite(RightDirectPin1, speed > 0 ? HIGH : LOW);
  digitalWrite(RightDirectPin2, speed < 0 ? HIGH : LOW);
  digitalWrite(LeftDirectPin1, speed > 0 ? HIGH : LOW);
  digitalWrite(LeftDirectPin2, speed < 0 ? HIGH : LOW);
  analogWrite(speedPinR, AVOID_SPEED);
  analogWrite(speedPinL, AVOID_SPEED);
  appliedRight = speed;
  appliedLeft = speed;
  return true;
}


void setup() {
  pinMode(speedPinR, OUTPUT);
  pinMode(RightDirectPin1, OUTPUT);
  pinMode(RightDirectPin2, OUTPUT);
  pinMode(speedPinL, OUTPUT);
  pinMode(LeftDirectPin1, OUTPUT);
  pinMode(LeftDirectPin2, OUTPUT);
  // 元の回路のブザーをOFF（LOWで鳴る想定）
  digitalWrite(13, HIGH);
  pinMode(13, OUTPUT);
  stopMotors();
  IrReceiver.begin(IR_RECEIVE_PIN, DISABLE_LED_FEEDBACK);
  setupObstacleDetection();  // 【追加】センサー初期化
}

void loop() {
  readRemote();
  checkHoldTimeout();
  // 【追加】Main.pngと同じ順序で状態を更新する
  updateUltrasonicState();
  updateRearInfraredState();
  updateVehicleState();
  updateBuzzerState();
  if (applyObstacleMovement()) {
    return;  // 障害物による後退・前進、または停止
  }
  driveMotors();
}

/* OSOYOO Model No.2019012400 / UNO / Model X
 * code.txtを参考に、提供フローチャートの関数順・速度を実装。
 * 必須の配線変更: 右ENA D9→D5、サーボ信号 D5→D9。
 * ServoがTimer1を使うため、D9/D10でモーターPWMは使わない。
 * 同じフォルダのFlowchartLogic.hとBoardPins.hが必要。実機走行は未検証。
 */
#include <Arduino.h>
#define IR_USE_AVR_TIMER2
#include <IRremote.hpp>  // Arduino-IRremote 4.x
#include <Servo.h>
#include "FlowchartLogic.h"

#include "BoardPins.h"
constexpr uint16_t IR_ADVANCE=24,IR_BACK=82,IR_RIGHT=90,IR_LEFT=8,IR_STOP=28;
constexpr unsigned long REMOTE_TIMEOUT_MS=350;
constexpr unsigned long SENSOR_PERIOD_MS=60;

Servo headServo;
flowcar::Controller controller;
flowcar::Sensors sensors={flowcar::INVALID,false};
flowcar::Output drive={0,0,false,0};
flowcar::Remote RM=flowcar::STOP;
uint8_t M=0;                       // 車両状態（設計書参照）
uint32_t remoteAt=0,sequence=0,lastSensorAt=0;
bool remoteSeen=false,sensorSeen=false;
bool buzzerWasActive=false;
uint32_t buzzerStarted=0;
int8_t appliedRight=0,appliedLeft=0;

// リモコン状態: 未受信/STOP=0、上=1、下=2、右=3、左=4。
void do_IR_Tick() {
  if(!IrReceiver.decode()) return;
  const uint8_t flags=IrReceiver.decodedIRData.flags;
  const uint16_t key=IrReceiver.decodedIRData.command;
  if(flags & IRDATA_FLAGS_WAS_OVERFLOW) {
    remoteSeen=false;RM=flowcar::STOP;
  } else if(flags & IRDATA_FLAGS_IS_REPEAT) {
    if(remoteSeen) remoteAt=millis(); // リピートを新しい操作として扱わない
  } else {
    flowcar::Remote next=flowcar::STOP;bool known=true;
    switch(key) {
      case IR_ADVANCE:next=flowcar::FORWARD;break;
      case IR_BACK:next=flowcar::BACKWARD;break;
      case IR_RIGHT:next=flowcar::RIGHT;break;
      case IR_LEFT:next=flowcar::LEFT;break;
      case IR_STOP:next=flowcar::STOP;break;
      default:known=false;break;
    }
    if(known) {RM=next;remoteSeen=true;remoteAt=millis();++sequence;}
  }
  IrReceiver.resume();
}

// 超音波センサの状態: 5cm以下、5cm超15cm以下、安全、計測失敗。
unsigned long watch() {
  digitalWrite(Trig_PIN,LOW);delayMicroseconds(2);
  digitalWrite(Trig_PIN,HIGH);delayMicroseconds(10);
  digitalWrite(Trig_PIN,LOW);
  return pulseIn(Echo_PIN,HIGH,15000UL);
}
void updateUltrasonicState() { sensors.front=flowcar::classifyFront(watch()); }
// 左右いずれかLOWなら後方検知。Mへ直接代入せず車両状態で統合する。
void updateRearIRState() {
  sensors.rear=digitalRead(LFSensor_bl)==LOW||digitalRead(LFSensor_br)==LOW;
}
void updateVehicleState() {
  const uint32_t now=millis();
  const bool linkAlive=remoteSeen&&uint32_t(now-remoteAt)<=REMOTE_TIMEOUT_MS;
  drive=flowcar::update(controller,sensors,RM,linkAlive,sequence,now);
  M=drive.m;
}
// ブザー状態: 50ms ON/OFFを2回、600ms周期。delayで制御を止めない。
void warning() {
  const uint32_t now=millis();
  if(drive.buzzer&&!buzzerWasActive) buzzerStarted=now;
  buzzerWasActive=drive.buzzer;
  const uint32_t t=uint32_t(now-buzzerStarted)%600UL;
  const bool on=drive.buzzer&&(t<50UL||(t>=100UL&&t<150UL));
  digitalWrite(BUZZ_PIN,on?LOW:HIGH);
}
void setMotor(uint8_t in1,uint8_t in2,uint8_t pwm,int8_t percent) {
  digitalWrite(in1,percent>0?HIGH:LOW);
  digitalWrite(in2,percent<0?HIGH:LOW);
  const uint8_t magnitude=percent<0?-percent:percent;
  analogWrite(pwm,(uint16_t(magnitude)*255U+50U)/100U);
}
void stop_Stop() {
  analogWrite(speedPinR,0);analogWrite(speedPinL,0);
  digitalWrite(RightDirectPin1,LOW);digitalWrite(RightDirectPin2,LOW);
  digitalWrite(LeftDirectPin1,LOW);digitalWrite(LeftDirectPin2,LOW);
  appliedRight=0;appliedLeft=0;
}
void do_Drive_Tick() {
  if(drive.right==0&&drive.left==0) {stop_Stop();return;}
  // 出力方向が変わる場合は、先に左右のPWMを0にする。
  if((appliedRight>0&&drive.right<0)||(appliedRight<0&&drive.right>0)||
     (appliedLeft>0&&drive.left<0)||(appliedLeft<0&&drive.left>0)) stop_Stop();
  setMotor(RightDirectPin1,RightDirectPin2,speedPinR,drive.right);
  setMotor(LeftDirectPin1,LeftDirectPin2,speedPinL,drive.left);
  appliedRight=drive.right;appliedLeft=drive.left;
}
void setup() {
  const uint8_t outputs[]={RightDirectPin1,RightDirectPin2,speedPinR,
      LeftDirectPin1,LeftDirectPin2,speedPinL,BUZZ_PIN,Trig_PIN};
  for(uint8_t pin:outputs) pinMode(pin,OUTPUT);
  stop_Stop();digitalWrite(BUZZ_PIN,HIGH);digitalWrite(Trig_PIN,LOW);
  pinMode(LFSensor_bl,INPUT);pinMode(LFSensor_br,INPUT);pinMode(Echo_PIN,INPUT);
  headServo.attach(SERVO_PIN);headServo.write(90);
  delay(400); // 起動時の正面合わせだけ。モーター停止中。
  IrReceiver.begin(IR_RECEIVE_PIN,DISABLE_LED_FEEDBACK);
}
void loop() {
  do_IR_Tick();                                      // 1. リモコン状態
  const uint32_t now=millis();
  if(!sensorSeen||uint32_t(now-lastSensorAt)>=SENSOR_PERIOD_MS) {
    updateUltrasonicState();                         // 2. 超音波センサ状態
    sensorSeen=true;lastSensorAt=now;
  }
  updateRearIRState();                               // 3. 赤外線センサ状態
  do_IR_Tick(); // pulseIn待機中に届いたSTOPを、出力前にも取り込む
  updateVehicleState();                              // 4. 車両状態
  warning();                                         // 5. ブザー状態
  do_Drive_Tick();                                    // 6. 行動状態
}

#ifndef FLOWCHART_LOGIC_H
#define FLOWCHART_LOGIC_H
#include <stdint.h>
namespace flowcar {
// RMは原図の値。右=3、左=4。
enum Remote : uint8_t { STOP=0, FORWARD=1, BACKWARD=2, RIGHT=3, LEFT=4 };
enum Front : uint8_t { CLEAR, CAUTION, EMERGENCY, INVALID };
enum Phase : uint8_t { MANUAL, BRAKING, ESCAPING, WAIT_NEW };
struct Sensors { Front front; bool rear; };
struct Output { int8_t right; int8_t left; bool buzzer; uint8_t m; };
struct Controller {
  Phase phase=WAIT_NEW;
  uint32_t started=0;
  uint32_t lastSequence=0;
  bool escapeBackward=false;
};
inline Front classifyFront(unsigned long echoUs) {
  if(echoUs==0) return INVALID;
  // 元コードと同じ換算係数0.01657。丸める前の距離で境界判定。
  const float cm=echoUs*0.01657f;
  if(cm<=5.0f) return EMERGENCY;
  if(cm<=15.0f) return CAUTION;
  return CLEAR;
}
inline Output stop(bool alarm=false,uint8_t m=0) { return {0,0,alarm,m}; }
inline Output manual(Remote rm) {
  switch(rm) {
    case FORWARD: return {50,50,false,3};
    case BACKWARD: return {-30,-30,false,4};
    case LEFT: return {30,-30,false,5};
    case RIGHT: return {-30,30,false,6};
    default: return stop();
  }
}
// 非ブロッキングの停止→反対方向10%→停止。回避完了後は新しい操作待ち。
inline Output update(Controller& c,Sensors s,Remote rm,bool linkAlive,
                     uint32_t sequence,uint32_t now) {
  const bool fresh=sequence!=c.lastSequence;
  c.lastSequence=sequence;
  const bool frontBlocked=s.front==CAUTION||s.front==EMERGENCY;
  const bool alarm=s.front==INVALID||frontBlocked||s.rear;
  if(!linkAlive||rm==STOP) { c.phase=WAIT_NEW;return stop(alarm); }
  if(s.front==INVALID) { c.phase=WAIT_NEW;return stop(true,8); }
  if(s.front==EMERGENCY) { c.phase=WAIT_NEW;return stop(true,1); }
  if(frontBlocked&&s.rear) { c.phase=WAIT_NEW;return stop(true,7); }
  if(c.phase==WAIT_NEW) {
    if(!fresh) return stop(alarm);
    c.phase=MANUAL;
  }
  if(c.phase==BRAKING||c.phase==ESCAPING) {
    // 回避方向も毎ループ監視。前後同時・5cm以下は上で停止する。
    const bool obstacleRemains=c.escapeBackward?frontBlocked:s.rear;
    if(!obstacleRemains) { c.phase=WAIT_NEW;return stop(alarm); }
    if(uint32_t(now-c.started)>=1500U) { c.phase=WAIT_NEW;return stop(true); }
    if(c.phase==BRAKING) {
      if(uint32_t(now-c.started)<100U) return stop(true,c.escapeBackward?1:2);
      c.phase=ESCAPING;
    }
    return c.escapeBackward?Output{-10,-10,true,1}:Output{10,10,true,2};
  }
  // 原図の「前方→後方→リモコン」の優先順。起動直後やSTOP中は自走しない。
  if(frontBlocked||s.rear) {
    c.escapeBackward=frontBlocked;
    c.started=now;c.phase=BRAKING;
    return stop(true,frontBlocked?1:2);
  }
  return manual(rm);
}
}
#endif

#ifndef FLOWCHART_BOARD_PINS_H
#define FLOWCHART_BOARD_PINS_H
#include <Arduino.h>
// ２.jpg / 4.jpg / 配線.jpg / 6.jpg / 3.jpg / 7.png を照合。
// false: 前版と同じ。true: 配線.jpgのEcho D2を採用し、右後方信号はA5へ移す。
// 切り替える場合はEchoと右後方センサーの実配線も変更する。
constexpr bool USE_PHOTO_ECHO_WIRING=false;
constexpr uint8_t IR_RECEIVE_PIN=4;
constexpr uint8_t speedPinR=5;       // 元code.txtの9から変更（ENAの線を移す）
constexpr uint8_t RightDirectPin1=12;
constexpr uint8_t RightDirectPin2=11;
constexpr uint8_t speedPinL=6;
constexpr uint8_t LeftDirectPin1=7;
constexpr uint8_t LeftDirectPin2=8;
constexpr uint8_t BUZZ_PIN=13;       // LOWで鳴動するアクティブブザー
constexpr uint8_t LFSensor_bl=0;     // code.txtを継承。D0のためSerialは使わない
constexpr uint8_t LFSensor_br=USE_PHOTO_ECHO_WIRING?A5:2;
constexpr uint8_t Echo_PIN=USE_PHOTO_ECHO_WIRING?2:3; // 画像はD2、code.txtはD3
